CREATE TABLE t9(id INTEGER,h INT,g INT,f INT,e INT,d INT,c INT,b INT,a INT); WITH RECURSIVE seq(v) AS (VALUES(1) UNION ALL SELECT v+1 FROM seq WHERE v<255) INSERT INTO t9 SELECT v,CASE WHEN (v&128)!=0 THEN 1 END,CASE WHEN (v&64)!=0 THEN 1 END,CASE WHEN (v&32)!=0 THEN 1 END,CASE WHEN (v&16)!=0 THEN 1 END,CASE WHEN (v&8)!=0 THEN 1 END,CASE WHEN (v&4)!=0 THEN 1 END,CASE WHEN (v&2)!=0 THEN 1 END,CASE WHEN (v&1)!=0 THEN 1 END FROM seq;